    /// <summary>Gets the decoding table for a named character set.</summary>
    /// <param name="name">The name as a dictionary spells it on its first line.</param>
    /// <param name="table">The 128 characters bytes 0x80-0xFF stand for.</param>
    /// <returns>Whether the name is one of the sets recorded here.</returns>
    public static bool TryGetTable(string name, out string table)
    {
        if (string.IsNullOrEmpty(name))
        {
            table = null;
            return false;
        }

        return Tables.TryGetValue(name, out table);
    }

    /// <summary>Gets the names this class answers for.</summary>
    public static IReadOnlyCollection<string> Names => Tables.Keys;
